import pandas as pd, numpy as np, html, math, re, json
from pathlib import Path
from collections import Counter

DATA='/app/benchmark/data.csv'
OUT=Path('/app/output/final_report.html')
OUT.parent.mkdir(parents=True, exist_ok=True)

df=pd.read_csv(DATA)

def clean_money(s):
    return pd.to_numeric(s.astype(str).str.replace('₹','',regex=False).str.replace(',','',regex=False).str.strip(), errors='coerce')
def clean_pct(s):
    return pd.to_numeric(s.astype(str).str.replace('%','',regex=False).str.strip(), errors='coerce')
def clean_count(s):
    return pd.to_numeric(s.astype(str).str.replace(',','',regex=False).str.strip().replace({'nan':np.nan}), errors='coerce')

df['discounted_price_num']=clean_money(df['discounted_price'])
df['actual_price_num']=clean_money(df['actual_price'])
df['discount_pct_num']=clean_pct(df['discount_percentage'])
df['rating_num']=pd.to_numeric(df['rating'], errors='coerce')
df['rating_count_num']=clean_count(df['rating_count'])
df['top_category']=df['category'].str.split('|').str[0]
df['sub_category']=df['category'].str.split('|').str[1].fillna('Unspecified')
df['deep_category']=df['category'].str.split('|').str[-1]
df['discount_band']=pd.cut(df['discount_pct_num'], bins=[-1,20,40,60,80,100], labels=['0–20%','21–40%','41–60%','61–80%','81–100%'])
df['price_band']=pd.cut(df['discounted_price_num'], bins=[-1,500,1000,5000,10000,10**12], labels=['≤₹500','₹501–₹1k','₹1k–₹5k','₹5k–₹10k','>₹10k'])
