# Helpers
BLUE='#2563eb'; TEAL='#0f766e'; ORANGE='#f97316'; RED='#dc2626'; GREEN='#16a34a'; PURPLE='#7c3aed'; DARK='#0f172a'; MUTED='#64748b'; GRID='#e2e8f0'; BG='#f8fafc'

def fmt_int(x):
    if pd.isna(x): return 'n/a'
    return f'{int(round(x)):,}'
def fmt_pct(x, d=1): return f'{x:.{d}f}%'
def fmt_num(x, d=2): return f'{x:.{d}f}'
def fmt_rupee(x):
    if pd.isna(x): return 'n/a'
    return '₹' + f'{int(round(x)):,}'
def esc(x): return html.escape(str(x))
def short(s, n=88):
    s=str(s)
    return s if len(s)<=n else s[:n-1]+'…'

def bar_chart(labels, values, title='', color=BLUE, width=760, height=330, value_fmt=lambda x:f'{x:.1f}', x_label=''):
    labels=list(labels); values=[0 if pd.isna(v) else float(v) for v in values]
    maxv=max(values) if values else 1
    left=170; right=42; top=36; bottom=30
    plot_w=width-left-right; plot_h=height-top-bottom
    n=len(values); gap=10; bar_h=(plot_h-gap*(n-1))/max(n,1)
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}">']
    parts.append(f'<rect width="{width}" height="{height}" fill="white" rx="18"/>')
    if title: parts.append(f'<text x="24" y="24" class="chart-title">{esc(title)}</text>')
    for i,(lab,val) in enumerate(zip(labels,values)):
        y=top+i*(bar_h+gap); w=(val/maxv)*plot_w if maxv else 0
        parts.append(f'<text x="{left-10}" y="{y+bar_h/2+5}" text-anchor="end" class="axis-label">{esc(lab)}</text>')
        parts.append(f'<rect x="{left}" y="{y}" width="{w}" height="{bar_h}" rx="6" fill="{color}" opacity="0.88"/>')
        parts.append(f'<text x="{left+w+8}" y="{y+bar_h/2+5}" class="value-label">{esc(value_fmt(val))}</text>')
    if x_label: parts.append(f'<text x="{left+plot_w/2}" y="{height-8}" text-anchor="middle" class="axis-label">{esc(x_label)}</text>')
    parts.append('</svg>')
    return ''.join(parts)

def column_chart(labels, values, title='', color=TEAL, width=760, height=330, value_fmt=lambda x:f'{x:.1f}', y_min=None, y_max=None):
    labels=list(labels); values=[0 if pd.isna(v) else float(v) for v in values]
    if y_min is None: y_min=min(0,min(values) if values else 0)
    if y_max is None: y_max=max(values) if values else 1
    if y_max==y_min: y_max=y_min+1
    left=58; right=26; top=42; bottom=70; plot_w=width-left-right; plot_h=height-top-bottom
    n=len(values); gap=16; bar_w=(plot_w-gap*(n-1))/max(n,1)
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}"><rect width="{width}" height="{height}" fill="white" rx="18"/>']
    if title: parts.append(f'<text x="24" y="25" class="chart-title">{esc(title)}</text>')
    for t in np.linspace(y_min,y_max,5):
        y=top+plot_h-(t-y_min)/(y_max-y_min)*plot_h
        parts.append(f'<line x1="{left}" x2="{width-right}" y1="{y}" y2="{y}" stroke="{GRID}"/>')
        parts.append(f'<text x="{left-8}" y="{y+4}" text-anchor="end" class="axis-label">{value_fmt(t)}</text>')
    for i,(lab,val) in enumerate(zip(labels,values)):
        x=left+i*(bar_w+gap); h=max(0,(val-y_min)/(y_max-y_min)*plot_h); y=top+plot_h-h
        parts.append(f'<rect x="{x}" y="{y}" width="{bar_w}" height="{h}" rx="7" fill="{color}" opacity="0.88"/>')
        parts.append(f'<text x="{x+bar_w/2}" y="{y-6}" text-anchor="middle" class="value-label">{esc(value_fmt(val))}</text>')
        parts.append(f'<text x="{x+bar_w/2}" y="{height-42}" text-anchor="middle" class="axis-label rotateish">{esc(lab)}</text>')
    parts.append('</svg>')
    return ''.join(parts)

def scatter_svg(x, y, color_by=None, title='', xlab='', ylab='', width=760, height=420, max_points=1465):
    data=pd.DataFrame({'x':x,'y':y,'cat':color_by}).dropna()
    if len(data)>max_points: data=data.sample(max_points, random_state=7)
    xmin,xmax=np.nanpercentile(data.x,[1,99]); ymin,ymax=np.nanpercentile(data.y,[1,99])
    # include actual min/max but cap outliers for readability
    left=68; right=34; top=42; bottom=58; plot_w=width-left-right; plot_h=height-top-bottom
    palette={'Electronics':BLUE,'Computers&Accessories':TEAL,'Home&Kitchen':ORANGE,'OfficeProducts':PURPLE}
    def sx(v): return left + (min(max(v,xmin),xmax)-xmin)/(xmax-xmin)*plot_w if xmax>xmin else left
    def sy(v): return top + plot_h - (min(max(v,ymin),ymax)-ymin)/(ymax-ymin)*plot_h if ymax>ymin else top
    parts=[f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}"><rect width="{width}" height="{height}" fill="white" rx="18"/>']
    if title: parts.append(f'<text x="24" y="26" class="chart-title">{esc(title)}</text>')
    for t in np.linspace(ymin,ymax,5):
        yy=sy(t); parts.append(f'<line x1="{left}" x2="{width-right}" y1="{yy}" y2="{yy}" stroke="{GRID}"/>')
        parts.append(f'<text x="{left-8}" y="{yy+4}" text-anchor="end" class="axis-label">{t:.1f}</text>')
    for t in np.linspace(xmin,xmax,5):
        xx=sx(t); parts.append(f'<line x1="{xx}" x2="{xx}" y1="{top}" y2="{top+plot_h}" stroke="{GRID}"/>')
        parts.append(f'<text x="{xx}" y="{height-34}" text-anchor="middle" class="axis-label">{t:.0f}</text>')
    for _,r in data.iterrows():
        c=palette.get(r.cat, '#94a3b8')
        parts.append(f'<circle cx="{sx(r.x):.1f}" cy="{sy(r.y):.1f}" r="3.2" fill="{c}" opacity="0.38"/>')
    parts.append(f'<text x="{left+plot_w/2}" y="{height-10}" text-anchor="middle" class="axis-label">{esc(xlab)}</text>')
    parts.append(f'<text transform="translate(16 {top+plot_h/2}) rotate(-90)" text-anchor="middle" class="axis-label">{esc(ylab)}</text>')
    lx=width-230; ly=52
    for i,(name,c) in enumerate(palette.items()):
        parts.append(f'<circle cx="{lx}" cy="{ly+i*19}" r="5" fill="{c}" opacity="0.8"/><text x="{lx+12}" y="{ly+i*19+4}" class="axis-label">{esc(name)}</text>')
    parts.append('</svg>')
    return ''.join(parts)

def table_html(rows, columns, fmts=None, class_name='data-table'):
    fmts=fmts or {}
    out=[f'<table class="{class_name}"><thead><tr>']
    for c in columns: out.append(f'<th>{esc(c[1] if isinstance(c,tuple) else c)}</th>')
    out.append('</tr></thead><tbody>')
    for _,row in rows.iterrows():
        out.append('<tr>')
        for c in columns:
            key=c[0] if isinstance(c,tuple) else c
            val=row[key]
            if key in fmts: val=fmts[key](val)
            out.append(f'<td>{esc(val)}</td>')
        out.append('</tr>')
    out.append('</tbody></table>')
    return ''.join(out)

